// OAuth 2.1 authorization code + PKCE flow (browser)
import { generateCodeVerifier, generateCodeChallenge } from 'pkce-challenge';

const verifier = generateCodeVerifier();       // random 43-128 char string
const challenge = await generateCodeChallenge(verifier); // SHA-256 hash, base64url

sessionStorage.setItem('pkce_verifier', verifier);

// Build authorization URL
const params = new URLSearchParams({
  response_type: 'code',
  client_id: 'my-spa',
  redirect_uri: 'https://app.example.com/callback', // exact match required
  scope: 'openid profile',
  code_challenge: challenge,
  code_challenge_method: 'S256',
});
window.location = `https://auth.example.com/authorize?${params}`;

// Verifying an OIDC ID token (Node.js with jose library)
import { createRemoteJWKSet, jwtVerify } from 'jose';

const JWKS = createRemoteJWKSet(
  new URL('https://accounts.google.com/.well-known/openid-configuration')
);

async function verifyIdToken(idToken) {
  const { payload } = await jwtVerify(idToken, JWKS, {
    issuer: 'https://accounts.google.com',
    audience: process.env.GOOGLE_CLIENT_ID,
  });
  // payload.sub is the stable unique user identifier
  return payload;
}

// WebAuthn / FIDO2 authentication ceremony (browser-side)
async function authenticate() {
  // 1. Fetch challenge from server (new random challenge per attempt)
  const options = await fetch('/auth/webauthn/challenge').then(r => r.json());

  // 2. Invoke FIDO2 authenticator (platform biometric or hardware key)
  const assertion = await navigator.credentials.get({
    publicKey: {
      challenge: base64urlDecode(options.challenge),
      rpId: 'app.example.com',       // origin-bound — lookalike domain will fail
      allowCredentials: options.allowCredentials,
      userVerification: 'required',  // require biometric / PIN / physical touch
      timeout: 60000,
    }
  });

  // 3. Send signed assertion to server for signature verification
  const result = await fetch('/auth/webauthn/verify', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      id: assertion.id,
      rawId: base64urlEncode(assertion.rawId),
      response: {
        authenticatorData: base64urlEncode(assertion.response.authenticatorData),
        clientDataJSON: base64urlEncode(assertion.response.clientDataJSON),
        signature: base64urlEncode(assertion.response.signature),
      },
    }),
  });
  return result.ok;
}

// iOS: public key pinning with URLSession
import Foundation
import CryptoKit

// SHA-256 hash of the server's SubjectPublicKeyInfo bytes
let PINNED_KEY_HASH = Data(base64Encoded: "your+base64+sha256+hash==")!

class PinnedSessionDelegate: NSObject, URLSessionDelegate {
    func urlSession(_ session: URLSession,
                    didReceive challenge: URLAuthenticationChallenge,
                    completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        guard challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
              let serverTrust = challenge.protectionSpace.serverTrust,
              let leafCert = SecTrustGetCertificateAtIndex(serverTrust, 0),
              let publicKey = SecCertificateCopyKey(leafCert),
              let keyData = SecKeyCopyExternalRepresentation(publicKey, nil) as Data? else {
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }
        // Prefix DER key data with SPKI header before hashing (omitted for brevity)
        let keyHash = Data(SHA256.hash(data: keyData))
        if keyHash == PINNED_KEY_HASH {
            completionHandler(.useCredential, URLCredential(trust: serverTrust))
        } else {
            completionHandler(.cancelAuthenticationChallenge, nil)  // pin mismatch
        }
    }
}

import bcrypt

def hash_password(plaintext: str) -> bytes:
    # Encode first; bcrypt operates on bytes
    # Note: bcrypt silently truncates at 72 bytes
    password_bytes = plaintext.encode('utf-8')
    salt = bcrypt.gensalt(rounds=12)  # cost factor 12
    return bcrypt.hashpw(password_bytes, salt)

def verify_password(stored_hash: bytes, plaintext: str) -> bool:
    return bcrypt.checkpw(plaintext.encode('utf-8'), stored_hash)

# To avoid 72-byte truncation for long passphrases:
import hashlib, base64
def prehash(plaintext: str) -> str:
    # SHA-256 produces 44-char base64 output, safely under 72 bytes
    digest = hashlib.sha256(plaintext.encode()).digest()
    return base64.b64encode(digest).decode()

# Detect dangling CNAME records (subdomain takeover candidates)
import dns.resolver
import socket

# Cloud service signatures that indicate a claimable resource
TAKEOVER_SIGNATURES = [
    "There isn't a GitHub Pages site here",
    "NoSuchBucket",
    "The specified bucket does not exist",
    "No such app",                   # Heroku
    "Fastly error: unknown domain",
]

def check_dangling_cname(subdomain: str) -> str | None:
    """Return takeover message if subdomain CNAME is dangling."""
    try:
        answers = dns.resolver.resolve(subdomain, 'CNAME')
        target = str(answers[0].target)
    except dns.resolver.NXDOMAIN:
        return None  # subdomain doesn't resolve at all
    except Exception:
        return None

    try:
        ip = socket.gethostbyname(target.rstrip('.'))
        import urllib.request
        body = urllib.request.urlopen(f"https://{subdomain}", timeout=5).read().decode()
        for sig in TAKEOVER_SIGNATURES:
            if sig in body:
                return f"DANGLING CNAME {subdomain} -> {target}: '{sig}'"
    except Exception:
        pass
    return None

from flask import Flask

app = Flask(__name__)

@app.after_request
def add_security_headers(response):
    # X-Frame-Options for broad browser support (legacy)
    response.headers['X-Frame-Options'] = 'SAMEORIGIN'

    # CSP frame-ancestors for modern browsers (overrides X-Frame-Options)
    existing_csp = response.headers.get('Content-Security-Policy', '')
    if 'frame-ancestors' not in existing_csp:
        response.headers['Content-Security-Policy'] = (
            existing_csp + "; frame-ancestors 'self';"
        )
    return response

// VULNERABLE: naive deep merge pollutes prototype
function vulnerableMerge(target, source) {
  for (const key in source) {
    if (typeof source[key] === 'object') {
      target[key] = target[key] || {};
      vulnerableMerge(target[key], source[key]);  // __proto__ passes through
    } else {
      target[key] = source[key];
    }
  }
}

// SAFE: block prototype-chain keys before merging
const BLOCKED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function safeMerge(target, source) {
  for (const key of Object.keys(source)) {  // Object.keys skips prototype chain
    if (BLOCKED_KEYS.has(key)) continue;    // block pollution vectors
    if (source[key] !== null && typeof source[key] === 'object') {
      target[key] = target[key] && typeof target[key] === 'object' ? target[key] : {};
      safeMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

import DOMPurify from 'dompurify';

// VULNERABLE: directly writing location.hash to innerHTML
function showGreeting() {
  const name = location.hash.slice(1);  // e.g. #<img src=x onerror=alert(1)>
  document.getElementById('greeting').innerHTML = `Hello, ${name}!`; // DOM XSS
}

// SECURE option 1: use textContent (safe, no HTML interpretation)
function showGreetingSafe1() {
  const name = location.hash.slice(1);
  document.getElementById('greeting').textContent = `Hello, ${name}!`;
}

// SECURE option 2: sanitize if HTML is needed
function showGreetingSafe2() {
  const rawHtml = location.hash.slice(1);
  document.getElementById('greeting').innerHTML = DOMPurify.sanitize(rawHtml);
}

# VULNERABLE: rendering user content without encoding
# (Flask with Jinja2 |safe filter bypasses auto-escaping)
@app.route('/comment/<int:comment_id>')
def show_comment_vulnerable(comment_id):
    comment = Comment.query.get_or_404(comment_id)
    # NEVER use |safe with user-controlled content
    return render_template_string('<p>{{ text|safe }}</p>', text=comment.text)

# SECURE: Jinja2 auto-escaping is enabled by default
# Do not disable it for user-controlled content
@app.route('/comment/<int:comment_id>')
def show_comment_secure(comment_id):
    comment = Comment.query.get_or_404(comment_id)
    # Auto-escaped: < becomes &lt;, > becomes &gt;, etc.
    return render_template('comment.html', text=comment.text)

from markupsafe import escape  # Jinja2's HTML escaping utility
from flask import request, render_template_string

# VULNERABLE: reflects query parameter directly into HTML
@app.route('/search')
def search_vulnerable():
    query = request.args.get('q', '')
    return f'<p>Results for: {query}</p>'  # XSS if query = <script>...

# SECURE: HTML-encode all user input before inserting into HTML
@app.route('/search')
def search_secure():
    query = request.args.get('q', '')
    safe_query = escape(query)  # < → &lt;  > → &gt;  & → &amp;
    return f'<p>Results for: {safe_query}</p>'

// DOM clobbering: how it works and how to prevent it

// --- VULNERABLE pattern ---
// app.js reads a global that can be clobbered by injected HTML:
// const allowed = window.allowedOrigins || ['https://app.example.com'];
// If attacker injects: <a id="allowedOrigins" href="https://evil.com">x</a>
// then window.allowedOrigins is the DOM element, not the array

// --- SAFE: never read security config from DOM globals ---
// Use a const defined before any attacker-controlled HTML is parsed
const ALLOWED_ORIGINS = Object.freeze(['https://app.example.com']);

// --- SAFE: DOMPurify with DOM clobbering protection ---
import DOMPurify from 'dompurify';

function sanitize(dirty) {
  return DOMPurify.sanitize(dirty, {
    // SANITIZE_DOM (default true): removes id/name that collide with known globals
    SANITIZE_DOM: true,
    // Optionally: strip all id/name attributes entirely if they're not needed
    FORBID_ATTR: ['id', 'name'],  // disable if you need id for legitimate use
  });
}

// Enable via CSP header:
// Content-Security-Policy: require-trusted-types-for 'script';
//                          trusted-types html-sanitizer

import DOMPurify from 'dompurify';

// Define the only approved HTML-injection policy in the app
const htmlPolicy = trustedTypes.createPolicy('html-sanitizer', {
  createHTML: (dirty) => DOMPurify.sanitize(dirty, {
    ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a'],
    ALLOWED_ATTR: ['href'],
  }),
});

// All innerHTML assignments must go through the policy:
function renderUserBio(element, bioText) {
  element.innerHTML = htmlPolicy.createHTML(bioText); // OK
  // element.innerHTML = bioText;  // TypeError: blocked by Trusted Types
}
